// On-demand entry (webhook from JARVIS's brain, Telegram or the screen): run research now, or resend
// the latest saved report. mode: "run" | "resend" | "auto" (auto = resend today's report if there is
// one, otherwise run now). Input: the latest research_report row from jarvis_memory.
const TZ = 'America/Toronto';
const body = ($('Webhook (run or resend)').first().json || {}).body || {};
const mode = ['run', 'resend', 'auto'].includes(body.mode) ? body.mode : 'auto';
const today = new Date().toLocaleDateString('en-CA', { timeZone: TZ });
let last = null;
const row = $input.first().json || {};
if (row.kind === 'research_report' && row.summary) { try { last = JSON.parse(row.summary); } catch (e) { last = null; } }
let action = mode;
if (mode === 'auto') action = last && last.day === today ? 'resend' : 'run';
if (action === 'resend' && !last) action = 'run';
// Do not start a second run within 15 minutes (a run takes a few minutes and uses CJ/SerpApi).
const store = $getWorkflowStaticData('global');
if (action === 'run' && store.lastRunAt && Date.now() - store.lastRunAt < 15 * 60 * 1000) action = last ? 'resend' : 'busy';
if (action === 'run') store.lastRunAt = Date.now();
const said = { run: "I'm running product research now. The top 5 will arrive on Telegram in a few minutes.",
               resend: `Sending ${last && last.day === today ? "today's" : 'the latest'} products${last ? ' (' + last.day + ')' : ''} to your Telegram now.`,
               busy: 'Product research is already running. The results will arrive on Telegram in a few minutes.' }[action];
const reply = { ok: true, action, day: last ? last.day : null, message: said,
  products: last ? last.items.map(i => String(i.text || '').split('\n')[0].replace(/<[^>]+>/g, '')) : [] };
return [{ json: { action, reply, last, keywords: Array.isArray(body.keywords) ? body.keywords : null } }];

// Resend the saved report: one photo message per product, then the summary (no new searches).
const d = $input.first().json;
const last = d.last || { items: [], summary: '' };
const note = last.day ? `\n<i>Resent from ${last.day}: saved results, no new searches.</i>` : '';
const items = last.items.map((it, i) => ({ json: { photo: it.photo, has_photo: !!it.photo, caption: it.caption, text: it.text,
  summary: (last.summary || '') + note, index: i } }));
return items.length ? items : [{ json: { photo: '', has_photo: false, caption: '', text: '', summary: (last.summary || 'No saved report yet.') + note, index: 0 } }];

// After the resent photos: the summary, plus the text of any product whose photo could not be sent.
const reports = $('Resend saved report').all().map(i => i.json);
const results = $input.all().map(i => i.json || {});
const failed = reports.filter((r, i) => r.text && (!results[i] || results[i].error || !r.has_photo));
let msg = reports.length ? reports[0].summary : '';
if (failed.length) msg = failed.map(r => r.text).join('\n\n') + '\n\n' + msg;
return [{ json: { report: msg.slice(0, 4000) } }];

// Research plan: which searches to run this time, and whether we need a new CJ token.
// Daily at 10:00 (Toronto) + on demand. Owner rules: see the product rules in "Screen products".
// Holiday season (Black Friday, Christmas): prefer CJ products already in a US or Canada warehouse
// (fast delivery), so every theme is searched in the CA and US warehouses, then in China.
const CONFIG = {
  keywords: [
    'kitchen gadget', 'kitchen organizer', 'pet grooming', 'pet bowl', 'home storage',
    'closet organizer', 'bathroom accessories', 'car organizer', 'winter car accessories',
    'phone stand', 'cable organizer', 'desk organizer', 'christmas decoration', 'gift for him',
    'travel accessories', 'cleaning brush', 'yoga accessories', 'camping gear',
  ],
  per_run: 3,              // themes per run (each theme = 3 CJ searches: CA, US, CN warehouses)
  page_size: 40,           // CJ sorts by how many stores list each product (orderBy=listedNum)
  warehouses: ['CA', 'US', 'CN'],
};
const store = $getWorkflowStaticData('global');
const start = (store.kwIndex || 0) % CONFIG.keywords.length;
const picked = [0, 1, 2].slice(0, CONFIG.per_run).map(i => CONFIG.keywords[(start + i) % CONFIG.keywords.length]);
store.kwIndex = start + CONFIG.per_run;
// Owner can force themes ("research phone stands") through the webhook or another workflow.
const inp = $input.first().json || {};
const forced = inp.keywords || (inp.body && inp.body.keywords) || null;
const keywords = Array.isArray(forced) && forced.length ? forced.slice(0, 3).map(k => String(k).slice(0, 40)) : picked;
const t = store.cjToken;
const tokenOk = t && t.value && t.expires && new Date(t.expires).getTime() - Date.now() > 24 * 3600 * 1000;
return [{ json: { run_id: 'research_' + Date.now().toString(36), keywords, page_size: CONFIG.page_size, warehouses: CONFIG.warehouses,
                  need_token: !tokenOk, token: tokenOk ? t.value : null } }];

// Keep the CJ access token (valid about 15 days; CJ limits how often a new one can be requested).
const r = $input.first().json || {};
const d = r.data || {};
const value = d.accessToken || d.access_token || null;
if (!value) throw new Error('CJ did not return an access token: ' + JSON.stringify(r).slice(0, 300));
const expires = d.accessTokenExpiryDate || new Date(Date.now() + 14 * 24 * 3600 * 1000).toISOString();
const store = $getWorkflowStaticData('global');
store.cjToken = { value, expires };
const plan = $('Research plan').first().json;
return [{ json: { ...plan, need_token: false, token: value } }];

// One item per theme and warehouse country -> one CJ product search each (CA, US, then CN).
const plan = $input.first().json;
const out = [];
for (const k of plan.keywords) for (const w of plan.warehouses || ['CN']) {
  const query = { pageNum: 1, pageSize: plan.page_size, productNameEn: k, orderBy: 'listedNum' };
  if (w !== 'CN') query.countryCode = w;   // CJ: products stocked in that country's warehouse
  out.push({ json: { keyword: k, warehouse: w, query, token: plan.token, page_size: plan.page_size, run_id: plan.run_id } });
}
return out;

// Screen CJ search results (no AI): owner's product rules, price band, de-duplicate, competition check, rank.
// Demand = how many stores already list the product on CJ (CJ returns results sorted by it), plus
// CJ's sales/order count when the API provides one. Products in a CA or US warehouse come first
// (holiday season: fast delivery). Keeps the best 12.
// ---- Product rules (owner decisions 2026-11-16) - shared by research and idea checks ----
// Electronics are allowed only WITHOUT batteries or chargers. Beauty stays out. Kids, food,
// supplements, medical and weapons stay out (extra Canadian rules). Anything that may need a
// certification is flagged, not hidden.
const RULES = {
  exclude: [
    [/batter|rechargeable|lithium|li-?ion|power ?bank|charg(er|ing)|cordless|wireless|bluetooth|solar|\bvape\b|e-?cig/i, 'has a battery or charger'],
    [/cosmetic|make ?up|lipstick|mascara|eyelash|eyeliner|skin ?care|serum|face cream|lotion|perfume|fragrance|nail (polish|art|gel)|hair (dye|color|colour)|beauty|facial|wig\b/i, 'beauty (kept out for now)'],
    [/\btoys?\b|\bkids?\b|child|children|baby|infant|toddler|nursery/i, "kids' product (Health Canada toy rules)"],
    [/\bfood\b|snack|supplement|vitamin|protein powder|\btea\b|coffee beans|candy/i, 'food or supplement'],
    [/medical|medicine|therapy|massager|blood pressure|thermometer|hearing aid|pain relief|posture corrector|orthopedic/i, 'medical claims (Health Canada)'],
    [/knife set|weapon|pepper spray|taser|stun|crossbow|airsoft|\bgun\b|cbd|nicotine/i, 'restricted item'],
  ],
  certification: [
    [/electr|\busb\b|\bled\b|lamp|\blights?\b|plug|\bac\b|adapter|110v|120v|220v|heater|heat(ed|ing)|motor|fan\b|humidifier|diffuser|kettle|blender|grinder|sensor|remote control/i,
     'electrical: plug-in or powered items need CSA, cUL or ETL marking to be sold in Canada; ask CJ for the certificate'],
    [/\bradio\b|\bwifi\b|wi-fi|\brf\b|transmitter|walkie|gps tracker|smart\b/i, 'radio device: needs ISED Canada certification'],
    [/cup|mug|bottle|bowl|plate|lunch ?box|cutting board|utensil|spatula|straw|food storage|container|baking|silicone mold/i,
     'touches food: ask CJ for a food-contact test report (FDA or LFGB)'],
    [/helmet|life ?jacket|car seat|seat ?belt|reflective vest/i, 'safety gear: may need certification (CSA or DOT)'],
    [/magnet/i, 'small magnets: Health Canada warns about swallowing; keep packaging adult-only'],
  ],
};
function checkRules(text) {
  const t = String(text || '');
  const excluded = RULES.exclude.filter(([re]) => re.test(t)).map(([, why]) => why);
  const certification = RULES.certification.filter(([re]) => re.test(t)).map(([, why]) => why);
  return { excluded: excluded.length ? excluded[0] : null, certification };
}
// ---- end of product rules ----
const MAX_COST_USD = 20;   // supplier price ceiling, before shipping
const searches = $('Searches').all().map(i => i.json);
const out = [], seen = new Set(), notes = [];
let excludedCount = 0;
$input.all().forEach((item, idx) => {
  const r = item.json || {};
  if (r.error) { notes.push(`search "${searches[idx]?.keyword}": request failed (${(r.error.message || JSON.stringify(r.error)).slice(0, 120)})`); return; }
  if (r.result === false || (r.code && r.code !== 200)) { notes.push(`search "${searches[idx]?.keyword}": CJ said ${r.message || r.code}`); return; }
  const d = r.data || {};
  let list = d.list || d.content || [];
  if (list.length && list[0] && Array.isArray(list[0].productList)) list = list.flatMap(x => x.productList);
  for (const p of list) {
    const pid = p.pid || p.id; if (!pid || seen.has(pid)) continue;
    const name = p.productNameEn || p.nameEn || p.productName || '';
    const cat = p.categoryName || p.threeCategoryName || '';
    const price = parseFloat(String(p.sellPrice ?? p.nowPrice ?? '').split('-')[0]);
    if (!name || !(price > 0) || price > MAX_COST_USD) continue;
    const rule = checkRules(name + ' ' + cat);
    if (rule.excluded) { excludedCount++; continue; }
    seen.add(pid);
    let image = p.productImage || p.bigImage || p.image || '';
    if (typeof image === 'string' && image.trim().startsWith('[')) { try { image = JSON.parse(image)[0] || ''; } catch { image = ''; } }
    if (Array.isArray(image)) image = image[0] || '';
    image = String(image || '').replace(/^http:/, 'https:');
    const sold = Number(p.saleNum ?? p.salesVolume ?? p.soldNum ?? p.orderNum ?? 0) || 0;
    out.push({ pid, name: name.slice(0, 120), category: cat, sku: p.productSku || p.sku || '',
               image: /^https:\/\//.test(image) ? image : '', list_price_usd: price,
               listed_by_stores: Number(p.listedNum ?? p.listedShopNum ?? 0) || 0, sold_count: sold,
               keyword: searches[idx]?.keyword || '', warehouse: searches[idx]?.warehouse || 'CN',
               certification: rule.certification, token: searches[0]?.token });
  }
});
const demand = x => x.listed_by_stores + 2 * x.sold_count;
out.forEach(x => { x.demand_score = demand(x); });

// Competition check (no AI). Two signals:
//  1. how many stores already sell it through CJ (more stores = proven, but also more competitors)
//  2. how many near-identical products came up in the same searches (copies of the same item)
// Bands: under 20 = unproven, 20-1999 = healthy (best), 2000-7999 = crowded, 8000+ = saturated.
const words = n => new Set(String(n).toLowerCase().replace(/[^a-z0-9 ]/g, ' ').split(/\s+/)
  .filter(w => w.length > 3 && !['with', 'for', 'and', 'the', 'from', 'pet', 'dog', 'cat', 'home', 'kitchen', 'tool', 'tools'].includes(w)));
const W = out.map(x => words(x.name));
out.forEach((x, i) => {
  x.similar_count = W.filter((w, j) => j !== i && [...W[i]].filter(t => w.has(t)).length >= 3).length;
  const n = x.listed_by_stores;
  x.competition = n < 20 ? 'unproven' : n < 2000 ? 'healthy' : n < 8000 ? 'crowded' : 'saturated';
});
const BAND = { healthy: 0, crowded: 1, unproven: 2, saturated: 3 };
const local = x => (x.warehouse === 'CA' || x.warehouse === 'US') ? 0 : 1;
out.sort((a, b) => (BAND[a.competition] >= 2) - (BAND[b.competition] >= 2) || local(a) - local(b) || (BAND[a.competition] - BAND[b.competition]) || (a.similar_count >= 4) - (b.similar_count >= 4) || b.demand_score - a.demand_score);
const keep = out.slice(0, 12);
if (excludedCount) notes.push(excludedCount + ' product(s) skipped by your rules (batteries/chargers, beauty, kids, food, medical)');
if (!keep.length) return [{ json: { empty: true, notes, token: searches[0]?.token } }];
return keep.map(p => ({ json: { ...p, screen_notes: notes } }));

// First sellable variant of each product: its id (needed for shipping), price and weight.
const prods = $('Screen products').all().map(i => i.json);
return $input.all().map((item, idx) => {
  const p = prods[idx]; const r = item.json || {};
  const vs = Array.isArray(r.data) ? r.data : (r.data && (r.data.variants || r.data.list)) || [];
  const v = vs.find(x => x && (x.vid || x.variantId)) || null;
  return { json: { ...p, vid: v ? (v.vid || v.variantId) : null,
                   variant_name: v ? (v.variantNameEn || v.variantName || '') : '',
                   cost_usd: v ? parseFloat(v.variantSellPrice ?? v.sellPrice ?? p.list_price_usd) || p.list_price_usd : p.list_price_usd,
                   weight_g: v ? Number(v.variantWeight ?? v.weight ?? 0) || null : null } };
});

// Finance 1 (pure arithmetic, no AI). Every number is an ESTIMATE from CJ's quoted prices.
const F = {
  usd_to_cad: 1.40,          // check the current rate before relying on results
  markup: 2.5,               // suggested retail = landed cost x markup, then rounded to .99
  min_profit_cad: 12,        // or at least this much above landed cost
  max_retail_cad: 60,        // owner's price ceiling
  payment_pct: 0.029, payment_fixed_cad: 0.30,   // card processing (verify on your Shopify plan)
  returns_pct: 0.05,         // allowance for refunds/returns
  marketing_pct: 0.20,       // allowance for ads/promotion per sale
  max_days: 20,              // longest acceptable delivery estimate to Canada
  // Owner's TARGETS (2026-11-10): products meeting both are listed first and marked 🎯
  target_profit_cad: 10,
  target_days: 10,
};
const prods = $('Pick variant').all().map(i => i.json);
const local = $('CJ shipping to Canada').all().map(i => i.json || {});
const out = [];
// Shipping quote: from the product's warehouse (CA/US) first; when CJ gives none to Canada from there,
// the backup quote from China is used and the product is marked as shipping from China.
$input.all().forEach((item, idx) => {
  const p = prods[idx];
  const toOpts = r => (Array.isArray(r && r.data) ? r.data : []).filter(o => parseFloat(o.logisticPrice ?? o.price) >= 0);
  let r = local[idx] || {}, from = p.warehouse || 'CN';
  if (!toOpts(r).length && from !== 'CN' && toOpts(item.json).length) { r = item.json; p.warehouse_note = 'CJ does not ship this to Canada from the ' + from + ' warehouse; quote is from China'; from = 'CN'; p.warehouse = 'CN'; }
  const opts = (Array.isArray(r.data) ? r.data : []).map(o => ({
    name: o.logisticName || o.name || '?', usd: parseFloat(o.logisticPrice ?? o.price), days: String(o.logisticAging || o.aging || '')
  })).filter(o => o.usd >= 0);
  const maxDays = o => { const n = (o.days.match(/\d+/g) || []).map(Number); return n.length ? Math.max(...n) : 99; };
  const ok = opts.filter(o => maxDays(o) <= F.max_days).sort((a, b) => a.usd - b.usd);
  const ship = ok[0] || opts.sort((a, b) => a.usd - b.usd)[0] || null;
  const landed_usd = p.cost_usd + (ship ? ship.usd : 0);
  const landed = +(landed_usd * F.usd_to_cad).toFixed(2);
  let price = Math.max(landed * F.markup, landed + F.min_profit_cad);
  price = Math.ceil(price) - 0.01;
  const fees = price * F.payment_pct + F.payment_fixed_cad;
  const profit = +(price - landed - fees - price * F.returns_pct - price * F.marketing_pct).toFixed(2);
  const flags = [];
  if (!p.vid) flags.push('no variant data');
  if (!ship) flags.push('no shipping quote to Canada');
  else if (maxDays(ship) > F.max_days) flags.push('slow delivery (' + ship.days + ' days)');
  if (price > F.max_retail_cad) flags.push('price above ' + F.max_retail_cad + ' CAD');
  if (profit < 8) flags.push('thin profit');
  if (p.competition === 'unproven') flags.push('unproven demand (few stores sell it yet)');
  if (p.competition === 'crowded') flags.push('crowded: ' + p.listed_by_stores + ' stores already sell it');
  if (p.competition === 'saturated') flags.push('saturated: ' + p.listed_by_stores + ' stores sell it, hard to stand out');
  (p.certification || []).forEach(c => flags.push('⚠️ ' + c));
  if (p.warehouse_note) flags.push(p.warehouse_note);
  if (p.similar_count >= 4) flags.push(p.similar_count + ' near-identical copies on CJ');
  const days = ship ? maxDays(ship) : 99;
  const meets_target = !!ship && profit >= F.target_profit_cad && days <= F.target_days;
  const misses = [];
  if (profit < F.target_profit_cad) misses.push('profit under ' + F.target_profit_cad + ' CAD');
  if (days > F.target_days) misses.push('delivery over ' + F.target_days + ' days');
  const local_warehouse = p.warehouse === 'CA' || p.warehouse === 'US';
  out.push({ json: { ...p, local_warehouse, meets_target, target_misses: misses, shipping: ship, landed_cad: landed, price_cad: +price.toFixed(2),
                     est_profit_cad: profit, margin_pct: Math.round(profit / price * 100), flags,
                     estimate_note: 'Estimates from CJ quotes; excludes sales tax, duties and samples.' } });
});
return out;

// Rank: no blocking flags first, then products meeting the owner's targets, then CA/US warehouse (holiday season),
// then competition band (healthy > crowded > unproven > saturated), then profit x demand.
// Keeps 8 candidates: the market check (SerpApi, limited free searches) then picks the final 5.
let all = $input.all().map(i => i.json);
// No shipping quote to Canada = the numbers are not real: keep such products out when others have a quote.
if (all.some(p => p.shipping)) all = all.filter(p => p.shipping);
const blocking = f => f.some(x => /no shipping|slow|above/.test(x));
const BAND = { healthy: 0, crowded: 1, unproven: 2, saturated: 3 };
all.sort((a, b) => (blocking(a.flags) - blocking(b.flags)) || (Number(!!b.meets_target) - Number(!!a.meets_target)) || (Number(!!b.local_warehouse) - Number(!!a.local_warehouse)) || (BAND[a.competition] - BAND[b.competition]) ||
                   (b.est_profit_cad * Math.log2(2 + b.demand_score) - a.est_profit_cad * Math.log2(2 + a.demand_score)));
const top = all.slice(0, 8);
const facts = top.map((p, i) => ({ n: i + 1, pid: p.pid, name: p.name, category: p.category, cost_usd: p.cost_usd,
  shipping: p.shipping, landed_cad: p.landed_cad, price_cad: p.price_cad, est_profit_cad: p.est_profit_cad,
  listed_by_stores: p.listed_by_stores, competition: p.competition, meets_targets: p.meets_target, similar_count: p.similar_count, sold_count: p.sold_count, flags: p.flags }));
const instructions = 'You are the JARVIS e-commerce research analyst for a new Shopify store selling in Canada. ' +
  'For each product below write one short note (max 25 words): who would buy it and the main risk. Use ONLY the facts given; ' +
  'do not invent sales numbers, trends, reviews or prices. Reply with JSON only: {"notes":[{"n":1,"note":"..."}]}';
return [{ json: { top, instructions, ai_body: { model: 'jarvis-free', max_tokens: 900, response_format: { type: 'json_object' },
  messages: [{ role: 'system', content: instructions }, { role: 'user', content: JSON.stringify(facts) }] } } }];

// Market check plan, within the FREE SerpApi plan (250 searches a month).
// Each fresh check = 2 searches (Google Shopping + Google Trends). Results are cached 10 days per
// product name and reused. A daily allowance spreads the month's searches; 40 are kept in reserve
// for the owner's own product-idea checks. Never goes over: when the budget is used up, products
// are sent as "market not checked" and the owner is warned.
const CFG = { monthly: 250, reserve_for_ideas: 40, max_per_day: 10, cache_days: 10, per_check: 2, warn_below: 60 };
const STOP = /\b(new|hot|sale|car styling|accessories|accessory|for|with|and|the|multi ?functional|portable|creative|household|tool|tools|1pc|pcs|set)\b/gi;
const store = $getWorkflowStaticData('global');
const TZ = 'America/Toronto';
const now = new Date();
const month = now.toLocaleDateString('en-CA', { timeZone: TZ }).slice(0, 7);
const today = now.toLocaleDateString('en-CA', { timeZone: TZ });
const s = store.serp && store.serp.month === month ? store.serp : (store.serp = { month, used: 0, days: {} });
store.serpCache = store.serpCache || {};
// Real numbers from the SerpApi account page (free, does not use a search). Fallback: own counter.
const acc = $input.first().json || {};
const hasKey = !acc.error && (acc.plan_searches_left !== undefined || acc.total_searches_left !== undefined);
const left = hasKey ? Number(acc.total_searches_left ?? acc.plan_searches_left) : Math.max(0, CFG.monthly - s.used);
const [y, m] = month.split('-').map(Number);
const daysInMonth = new Date(y, m, 0).getDate();
const daysLeft = daysInMonth - Number(today.slice(8, 10)) + 1;
const usedToday = s.days[today] || 0;
let allowance = Math.max(0, Math.min(CFG.max_per_day - usedToday, Math.floor((left - CFG.reserve_for_ideas) / daysLeft)));
const top = $('Shortlist').first().json.top || [];
const fresh = [], plan = [];
top.forEach((p, i) => {
  const q = String(p.name).split(/[-,|(]/)[0].replace(STOP, ' ').replace(/\s+/g, ' ').trim().split(' ').slice(0, 5).join(' ') || String(p.name).slice(0, 40);
  const key = q.toLowerCase();
  const c = store.serpCache[key];
  if (c && Date.now() - c.at < CFG.cache_days * 864e5) { plan.push({ i, q, source: 'cache' }); return; }
  if (fresh.some(f => f.q.toLowerCase() === key)) { plan.push({ i, q, source: 'same' }); return; }   // same name: one check
  if (hasKey && allowance >= CFG.per_check) { allowance -= CFG.per_check; fresh.push({ i, q }); plan.push({ i, q, source: 'fresh' }); return; }
  plan.push({ i, q, source: hasKey ? 'budget' : 'no_key' });
});
// Remove cache entries older than 30 days so the workflow data stays small.
for (const [k, v] of Object.entries(store.serpCache)) if (Date.now() - v.at > 30 * 864e5) delete store.serpCache[k];
const planned = fresh.length * CFG.per_check;
const leftAfter = left - planned;
let warning = null;
if (!hasKey) warning = null;   // reported separately as "SerpApi key missing"
else if (leftAfter <= CFG.reserve_for_ideas) warning = `⚠️ SerpApi: only ${leftAfter} free searches left this month. I'm keeping them for your own product checks, so daily market checks use saved results until the 1st. I never go over the free plan without your OK.`;
else if (leftAfter < CFG.warn_below) warning = `⚠️ SerpApi: ${leftAfter} free searches left this month (plan 250). I'm using saved results more to stay free.`;
const meta = { month, today, has_key: hasKey, key_error: acc.error ? String(acc.error.message || acc.error).slice(0, 120) : null,
               left_before: left, planned, left_after: leftAfter, plan, warning };
store.serpLastPlan = meta;
if (!fresh.length) return [{ json: { none: true, meta } }];
return fresh.map(f => ({ json: { ...f, meta } }));

// Market check (SerpApi: Google Shopping Canada prices + Google Trends Canada, last 3 months).
// Fresh results come from the two SerpApi nodes; others from the 10-day cache (see Market check items).
// Pass = market price >= 2x our landed cost and searches not falling. 🔥 = rising + 2.5x gap + owner targets.
// Final list (max 5): passed first (🔥 first, then CA/US warehouse), then "market not checked yet"
// (saving free searches) - products that failed the market check are dropped.
const store = $getWorkflowStaticData('global');
const s = $('Shortlist').first().json;
const metaItem = $('Market check items').first().json;
const meta = metaItem.meta;
let freshItems = [], shop = [], trends = [];
if (!metaItem.none) {
  freshItems = $('Market check items').all().map(i => i.json);
  try { shop = $('Google Shopping (Canada)').all().map(i => i.json || {}); } catch (e) { shop = []; }
  try { trends = $('Google Trends (Canada)').all().map(i => i.json || {}); } catch (e) { trends = []; }
}
const USD_TO_CAD = 1.40;
const median = a => { const b = [...a].sort((x, y) => x - y); return b.length ? (b.length % 2 ? b[(b.length - 1) / 2] : (b[b.length / 2 - 1] + b[b.length / 2]) / 2) : null; };
const errText = e => String((e && (e.message || e.description)) || (typeof e === 'string' ? e : JSON.stringify(e))).slice(0, 100);
function analyse(sh, tr) {
  const results = sh.shopping_results || [];
  const prices = results.map(r => Number(r.extracted_price)).filter(x => x > 0 && x < 1000);
  const amazon = results.filter(r => /amazon/i.test(r.source || '')).map(r => Number(r.extracted_price)).filter(x => x > 0);
  const tl = ((tr.interest_over_time || {}).timeline_data || []).map(t => Number(((t.values || [])[0] || {}).extracted_value) || 0);
  let trend = null, trend_pct = null;
  if (tl.length >= 8) {
    const avg = a => a.reduce((x, y) => x + y, 0) / a.length;
    const first = avg(tl.slice(0, 4)), last = avg(tl.slice(-4));
    trend_pct = first > 0 ? Math.round((last - first) / first * 100) : (last > 0 ? 100 : 0);
    trend = trend_pct >= 20 ? 'rising' : trend_pct <= -20 ? 'falling' : 'flat';
  }
  return { median_price_cad: prices.length >= 3 ? +median(prices).toFixed(2) : null, offers: prices.length,
           amazon_median_cad: amazon.length ? +median(amazon).toFixed(2) : null, amazon_offers: amazon.length,
           top_sources: [...new Set(results.map(r => r.source).filter(Boolean))].slice(0, 5), trend, trend_pct,
           error: sh.error || tr.error ? errText(sh.error || tr.error) : null };
}
// Store fresh results in the cache and count the searches used.
let usedNow = 0;
freshItems.forEach((f, k) => {
  const sh = shop[k] || {}, tr = trends[k] || {};
  if (shop[k]) usedNow++;
  if (trends[k]) usedNow++;
  const a = analyse(sh, tr);
  if (!a.error && (a.median_price_cad !== null || a.trend !== null)) store.serpCache[f.q.toLowerCase()] = { at: Date.now(), ...a };
  f.result = a;
});
if (store.serp && store.serp.month === meta.month) {
  store.serp.used += usedNow;
  store.serp.days[meta.today] = (store.serp.days[meta.today] || 0) + usedNow;
}
let checked = 0;
const enriched = s.top.map((p, i) => {
  const pl = meta.plan.find(x => x.i === i) || { q: '', source: 'no_key' };
  let a = null;
  if (pl.source === 'fresh') a = (freshItems.find(f => f.i === i) || {}).result || null;
  if (pl.source === 'same') a = (freshItems.find(f => f.q.toLowerCase() === pl.q.toLowerCase()) || {}).result || null;
  if (pl.source === 'cache') a = store.serpCache[pl.q.toLowerCase()] || null;
  if (!a || (a.median_price_cad === null && a.trend === null)) {
    return { ...p, market: { query: pl.q, checked: false, why: pl.source === 'budget' ? 'saving free searches' : pl.source === 'no_key' ? 'no SerpApi key' : (a && a.error) || 'no market data',
                             median_price_cad: null, ratio: null, trend: null, hot: false, pass: false } };
  }
  checked++;
  const ratio = a.median_price_cad ? +(a.median_price_cad / p.landed_cad).toFixed(1) : null;
  const hot = ratio !== null && ratio >= 2.5 && a.trend === 'rising' && p.meets_target;
  const pass = ratio !== null && ratio >= 2 && a.trend !== 'falling';
  return { ...p, market: { query: pl.q, checked: true, cached: pl.source === 'cache', ...a, ratio, hot, pass } };
});
const passed = enriched.filter(p => p.market.checked && p.market.pass)
  .sort((a, b) => Number(b.market.hot) - Number(a.market.hot));   // otherwise keep the shortlist ranking
const unchecked = enriched.filter(p => !p.market.checked);
const failed = enriched.filter(p => p.market.checked && !p.market.pass);
const kept = [...passed, ...unchecked].slice(0, 5);
const marketOk = meta.has_key && checked > 0;
const facts = kept.map((p, n) => ({ n: n + 1, name: p.name, landed_cad: p.landed_cad, price_cad: p.price_cad, est_profit_cad: p.est_profit_cad,
  warehouse: p.warehouse, market_median_price_cad: p.market.median_price_cad, price_gap: p.market.ratio, search_trend: p.market.trend, competition: p.competition, flags: p.flags }));
const instructions = 'You are the JARVIS e-commerce research analyst for a new Shopify store selling in Canada. ' +
  'For each product write one short note (max 25 words): who would buy it, whether the market price leaves room, and the main risk. Use ONLY the facts given; ' +
  'do not invent sales numbers, trends, reviews or prices. Reply with JSON only: {"notes":[{"n":1,"note":"..."}]}';
return [{ json: { ...s, top: kept, all_checked: enriched, market_ok: marketOk, dropped: failed.length, unchecked: kept.filter(p => !p.market.checked).length,
  serp: { has_key: meta.has_key, used_now: usedNow, left: meta.left_before - usedNow, warning: meta.warning, key_error: meta.key_error },
  ai_body: { model: 'jarvis-free', max_tokens: 900, response_format: { type: 'json_object' },
    messages: [{ role: 'system', content: instructions }, { role: 'user', content: JSON.stringify(facts) }] } } }];

// One photo message per product (caption = the facts), then a short summary message.
// Works with or without the AI notes and with or without images.
const s = $('Market verdict').first().json;
const plan = $('Research plan').first().json;
const esc = t => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
let notes = {};
try {
  const r = $input.first().json || {};
  const txt = (r.choices && r.choices[0] && r.choices[0].message && r.choices[0].message.content || '').replace(/^\s*```(?:json)?|```\s*$/g, '');
  for (const x of (JSON.parse(txt).notes || [])) notes[x.n] = x.note;
} catch (e) { /* AI notes are optional */ }
const items = s.top.map((p, i) => {
  const lines = [
    `<b>${i + 1}. ${esc(p.name)}</b>`,
    `${{ healthy: '🟢', crowded: '🟠', saturated: '🔴', unproven: '⚪' }[p.competition] || ''} Competition: ${p.competition} (${p.listed_by_stores} stores on CJ` +
      (p.similar_count ? `, ${p.similar_count} similar` : '') + ')' + (p.sold_count ? ` · ${p.sold_count} sold` : ''),
    `Cost ${p.cost_usd.toFixed(2)} USD + shipping ${p.shipping ? p.shipping.usd.toFixed(2) + ' USD (' + esc(p.shipping.name) + ', ' + esc(p.shipping.days) + ' days)' : 'unknown'}`,
    `Landed ~${p.landed_cad} CAD | price ${p.price_cad} CAD | est. profit ${p.est_profit_cad} CAD (${p.margin_pct}%)`,
    p.market && p.market.checked ? `${p.market.hot ? '🔥 ' : ''}Market${p.market.cached ? ' (saved check)' : ''}: ` +
      (p.market.median_price_cad ? `others sell at ~${p.market.median_price_cad} CAD (${p.market.ratio}× your cost)` : 'price n/a') +
      (p.market.amazon_median_cad ? `, Amazon.ca ~${p.market.amazon_median_cad} CAD` : '') +
      (p.market.trend ? `, Google searches ${p.market.trend} (${p.market.trend_pct > 0 ? '+' : ''}${p.market.trend_pct}% in 3 months)` : '')
      : 'Market: not checked yet' + (p.market && p.market.why ? ' (' + esc(p.market.why) + ')' : ''),
    `${p.local_warehouse ? '🚚 ' + esc(p.warehouse) + ' warehouse' : '📦 ships from China'} · CJ SKU ${esc(p.sku || p.pid)}`,
    p.meets_target ? '🎯 Meets your targets (10+ CAD profit, 10 days or less)' : '✖️ Misses target: ' + esc((p.target_misses || []).join(', ')),
  ];
  if (p.flags.length) lines.push('Watch: ' + esc(p.flags.join('; ')));
  if (notes[i + 1]) lines.push('<i>' + esc(notes[i + 1]) + '</i>');
  return { json: { photo: p.image || '', has_photo: !!p.image, caption: lines.join('\n').slice(0, 1000), text: lines.join('\n') } };
});
const day = new Date().toLocaleDateString('en-CA', { timeZone: 'America/Toronto', weekday: 'long', month: 'long', day: 'numeric' });
const sp = s.serp || {};
const summary = `<b>JARVIS daily products</b> · ${esc(day)} (${esc(plan.keywords.join(', '))})\n` +
  (s.top.length ? s.top.length + ' products above, best first. ' : 'No product passed today.\n') +
  (sp.has_key ? (s.dropped ? s.dropped + ' removed by the market check (market price too low or searches falling). ' : '') +
      (s.unchecked ? s.unchecked + ' not market-checked yet (saving free searches, or no market data). ' : '') + `SerpApi: ${sp.left} free searches left this month.\n`
    : 'Market check off: SerpApi key missing or not working' + (sp.key_error ? ' (' + esc(sp.key_error) + ')' : '') + '.\n') +
  (sp.warning ? esc(sp.warning) + '\n' : '') +
  '🔥 searches rising + others sell at 2.5x+ your cost · 🎯 10+ CAD profit and 10 days or less · 🚚 US/Canada warehouse (fast for Black Friday and Christmas)\n' +
  '🟢 healthy · 🟠 crowded · 🔴 saturated · ⚪ unproven · ⚠️ may need a certification\n' +
  'Estimates from CJ quotes (USD to CAD at 1.40), before sales tax and duties. Nothing was ordered or published.\n' +
  'To check your own idea, send me a link, a photo or a name. Say "resend the products" any time.';
if (!items.length) return [{ json: { photo: '', has_photo: false, caption: '', text: '', summary, index: 0 } }];   // nothing passed: summary only
return items.map((it, i) => ({ json: { ...it.json, summary, index: i } }));

// Nothing passed the screen: tell the owner why instead of staying silent.
const r = $input.first().json || {};
const plan = $('Research plan').first().json;
const why = (r.notes && r.notes.length) ? r.notes.join('; ') : 'no product passed the filters (price, excluded categories)';
return [{ json: { report: 'JARVIS product research (' + plan.keywords.join(', ') + '): no candidates this time. ' + why.replace(/[<>&]/g, ' ') } }];

// After the product photos (runs once): the summary, plus the full text of any product whose photo
// could not be sent (no image, or Telegram rejected it), so nothing is lost.
const reports = $('Report').all().map(i => i.json);
const results = $input.all().map(i => i.json || {});
const failed = reports.filter((r, i) => r.text && (!results[i] || results[i].error || !r.has_photo));
let msg = reports.length ? reports[0].summary : '';
if (failed.length) msg = failed.map(r => r.text).join('\n\n') + '\n\n' + msg;
return [{ json: { report: msg.slice(0, 4000) } }];

// What JARVIS says out loud after the report (spoken by the free Piper voice on the server). Short, factual, and only about what really happened.
let top = [];
try { top = $('Market verdict').first().json.top || []; } catch (e) { top = []; }
const hNum = Number(new Date().toLocaleString('en-CA', { timeZone: 'America/Toronto', hour: '2-digit', hour12: false })) % 24;
const hour = ((hNum % 12) || 12) + (hNum < 12 ? ' AM' : ' PM');
const NAME = 'Zohrab';
const greet = hNum < 12 ? 'Good morning' : hNum < 18 ? 'Good afternoon' : 'Good evening';
let text;
if (top.length) {
  const hits = top.filter(p => p.meets_target).length;
  const hot = top.filter(p => p.market && p.market.hot).length;
  const best = [...top].sort((a, b) => b.est_profit_cad - a.est_profit_cad)[0];
  const shortName = best.name.split(/[-,|]/)[0].trim().split(/\s+/).slice(0, 6).join(' ');
  text = `${greet}, ${NAME}. It's ${hour}. I've just sent today's products to your Telegram: ${top.length} product${top.length === 1 ? '' : 's'}, with photos, shipping times to Canada and profit estimates. ` +
         `The highest estimated profit is about ${Math.round(best.est_profit_cad)} dollars per sale, on the ${shortName}. ` +
         (hot ? `${hot} look${hot === 1 ? 's' : ''} hot: searches rising and a good price gap. ` : '') + (hits ? `${hits} meet${hits === 1 ? 's' : ''} your targets. ` : 'None met both of your targets today. ') + `These are estimates only; nothing has been ordered. Have a look when you have a moment.`;
} else {
  text = `${greet}, ${NAME}. I ran today's product research, but no product passed the filters this time. The details are in your Telegram.`;
}
return [{ json: { tts_body: { text: text.slice(0, 1200), lang: 'en', format: 'mp3' }, spoken_text: text } }];

// Two memory rows: a short summary (screen, briefing, JARVIS's answers) and the full report
// (kind research_report) so "resend the products" works without searching again.
let top = [];
try { top = $('Market verdict').first().json.top || []; } catch (e) { top = []; }
const plan = $('Research plan').first().json;
const day = new Date().toLocaleDateString('en-CA', { timeZone: 'America/Toronto' });
const list = top.map((p, i) => `${i + 1}. ${p.name.split(/[-,|]/)[0].trim().slice(0, 60)} (CJ SKU ${p.sku || p.pid}, ${p.warehouse || 'CN'} warehouse, landed ${p.landed_cad} CAD, price ${p.price_cad} CAD, est. profit ${p.est_profit_cad} CAD, competition ${p.competition}${p.meets_target ? ', meets targets' : ''}${p.market && p.market.median_price_cad ? ', market ~' + p.market.median_price_cad + ' CAD' : ''}${p.market && p.market.trend ? ', searches ' + p.market.trend : ''}${p.market && p.market.hot ? ', HOT' : ''})`).join('; ');
const summary = `Daily product research sent to the owner's Telegram on ${day} at 10:00 or on request (themes: ${plan.keywords.join(', ')}), with photos and a voice message. ` +
  (top.length ? `Top products: ${list}. Estimates only; nothing ordered.` : 'No product passed the filters.');
let reports = [];
try { reports = $('Report').all().map(i => i.json); } catch (e) { reports = []; }
let fallback = '';
try { fallback = $('Nothing-found report').first().json.report || ''; } catch (e) { fallback = ''; }
const full = { day, keywords: plan.keywords,
  items: reports.filter(r => r.text).map(r => ({ photo: r.photo || '', caption: r.caption, text: r.text })),
  summary: reports.length ? reports[0].summary : fallback };
return [{ json: { kind: 'research', summary: summary.slice(0, 1800) } },
        { json: { kind: 'research_report', summary: JSON.stringify(full).slice(0, 20000) } }];
